UPDATE order_message_outbox SET status='PENDING',next_attempt_at=CURRENT_TIMESTAMP(6),
    lease_token=NULL,locked_until=NULL,last_error='购买任务尚未完成，恢复重投'
WHERE trace_id=#{trace} AND event_type='ORDER_BUILD' AND status='SENT' AND sent_at<=#{cutoff}

UPDATE order_message_outbox SET status = 'SENT', broker_msg_id = #{messageId},
       sent_at = CURRENT_TIMESTAMP(6), lease_token = NULL, locked_until = NULL, last_error = NULL
WHERE event_id = #{id} AND status = 'SENDING' AND lease_token = #{token}

UPDATE order_message_outbox SET status = 'PENDING', next_attempt_at = #{next},
       lease_token = NULL, locked_until = NULL, last_error = #{error}
WHERE event_id = #{id} AND status = 'SENDING' AND lease_token = #{token}
